#define STB_IMAGE_IMPLEMENTATION
#include "../stb_image.h"
#include <stdio.h>
#include <stdlib.h>
int main(int argc, char** argv) {
    FILE* f = fopen(argv[1], "rb");
    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
    unsigned char* data = malloc(sz); fread(data, 1, sz, f); fclose(f);
    int x, y, channels;
    if (!stbi_info_from_memory(data, sz, &x, &y, &channels)) { printf("info failed\n"); return 0; }
    printf("info: %dx%d ch=%d\n", x, y, channels);
    unsigned char* img = stbi_load_from_memory(data, sz, &x, &y, &channels, 4);
    printf("load: %p %dx%d\n", (void*)img, x, y);
    free(img); free(data);
    return 0;
}
EOF
